const CryptoJS = require('crypto-js');
test("abc", () => {
  expect(CryptoJS.MD5("abc").toString()).to.equal("900150983cd24fb0d6963f7d28e17f72");
  expect(CryptoJS.SHA1("abc").toString()).to.equal("a9993e364706816aba3e25717850c26c9cd0d89d");
  expect(CryptoJS.SHA224("abc").toString()).to.equal("23097d223405d8228642a477bda255b32aadbce4bda0b3f7e36c9da7");
  expect(CryptoJS.SHA256("abc").toString()).to.equal("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
  expect(CryptoJS.SHA384("abc").toString()).to.equal("cb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed8086072ba1e7cc2358baeca134c825a7");
  expect(CryptoJS.SHA512("abc").toString()).to.equal("ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f");
});
test("empty and unicode", () => {
  expect(CryptoJS.SHA256("").toString(CryptoJS.enc.Hex)).to.equal("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
  expect(CryptoJS.MD5("übung").toString()).to.equal("530ca1d6029c45b7213d17c274017abe");
});
